/**
 * Produce and apply `deep` patches from JavaScript.
 *
 * This is the JavaScript half of github.com/brunoga/deep: the same patch wire
 * format, so a Go server and a browser can send each other changes rather
 * than whole documents. The format is specified in docs/wire-patch.md, and
 * this implementation is checked against a conformance corpus generated by
 * the Go one.
 *
 * ```ts
 * import { diff, applyPatch, reverse } from '@brunoga/deep-patch';
 *
 * const patch = diff(before, after);        // send this
 * const result = applyPatch(replica, patch); // on the other side
 * applyPatch(replica, reverse(patch));       // and undo it
 * ```
 */
export { applyPatch, GuardNotMetError, PathNotAllowedError } from "./apply.js";
export { diff } from "./diff.js";
export { reverse } from "./reverse.js";
export { merge } from "./merge.js";
export { evaluate, checkType } from "./conditions.js";
export { equal, clone } from "./equal.js";
export { buildPath, encloses, escapeKey, lastToken, parentPath, parsePath, removeAt, resolve, setAt, unescapeKey, } from "./path.js";
